function icon(name,cls=''){const d=ICONS[name]||ICONS.file;return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${d}"/></svg>`}
const BRAND_FILES={
  facebook:'facebook-official.svg',instagram:'instagram.svg',whatsapp:'whatsapp-official.svg',
 mercadolibre:'mercadolibre-transparent.svg',mercadopago:'mercadopago.svg',resend:'resend-official.svg',
 supabase:'supabase.svg',cloudflare:'cloudflare.svg',googleanalytics:'googleanalytics.svg',canva:'canva-color.svg',
  linkedin:'linkedin.svg',openai:'openai.svg'
};
function brand(name,cls=''){const file=BRAND_FILES[name]||`${name}.svg`;return `<img class="brand-logo brand-${name} ${cls}" src="./assets/brands/${file}" alt="" aria-hidden="true">`}
const TOKEN_ICONS={'💬':'message','💵':'dollar','💰':'dollar','💲':'dollar','📄':'file','✅':'check','🛠':'briefcase','🔎':'search','⏳':'clock','👥':'users','📅':'calendar','📢':'megaphone','🎂':'gift','🔗':'link','⚠':'shield','↻':'refresh','▤':'database','👁':'eye','⬇':'upload','🔒':'lock','⚡':'zap','🏢':'briefcase','🤖':'settings','🌐':'link','🗄':'database','🎁':'gift','📊':'chart','⚙':'settings','☷':'layers','📤':'upload','🔄':'refresh','✉':'message','⌖':'link','🔑':'lock'};
function replaceIconTokens(html){for(const [t,n] of Object.entries(TOKEN_ICONS))html=html.split(t).join(icon(n));return html}


const CVSTUDIO_LEVELS={
  Aprendiz:{rank:1,commission:10,modules:['inicio','clientes','plantillas','archivos','calendario'],actions:['send-message','job-detail','upload-file']},
  Operario:{rank:2,commission:15,modules:['inicio','clientes','plantillas','archivos','calendario'],actions:['send-message','new-job','job-detail','change-status','upload-file']},
  Líder:{rank:3,commission:18,modules:['inicio','clientes','calendario','plantillas','archivos','colaboradores'],actions:['send-message','new-client','new-job','job-detail','change-status','deliver-work','upload-file']},
  Supervisor:{rank:4,commission:20,modules:['inicio','clientes','administracion','marketing','calendario','plantillas','archivos','colaboradores','generador-url'],actions:['*']},
  Director:{rank:5,commission:20,modules:['*'],actions:['*']}
};
window.CVSTUDIO_LEVELS=CVSTUDIO_LEVELS;
window.CVStudioAccess={level:'Aprendiz',collaborator:null,ready:false,canModule(id){const p=CVSTUDIO_LEVELS[this.level]||CVSTUDIO_LEVELS.Aprendiz;return p.modules.includes('*')||p.modules.includes(id)},canAction(action){const p=CVSTUDIO_LEVELS[this.level]||CVSTUDIO_LEVELS.Aprendiz;return p.actions.includes('*')||p.actions.includes(action)},set(level,collab){this.level=CVSTUDIO_LEVELS[level]?level:'Aprendiz';this.collaborator=collab||null;this.ready=true;document.dispatchEvent(new CustomEvent('cvstudio:access-ready',{detail:{level:this.level}}));}};

