const kpi = (iconName,label,value,trend,accent) => `<article class="kpi-card" style="--accent:${accent}"><div class="kpi-icon">${TOKEN_ICONS[iconName]?icon(TOKEN_ICONS[iconName]):icon(iconName)}</div><div><small>${label}</small><strong>${value}</strong><span class="trend">${trend}</span></div></article>`;
const panel = (title,body,extra='') => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${extra}</div></div>${body}</section>`;

function nav(){
  const n=document.getElementById('mainNav');
  const visibleModules=modules.filter(([id])=>!window.CVStudioAccess?.ready||window.CVStudioAccess.canModule(id));
  n.innerHTML=visibleModules.map(([id,ic,name])=>`<button class="nav-item ${id===currentModule?'is-active':''}" data-module="${id}"><span class="nav-icon">${icon(ic)}</span><span>${name}</span></button>`).join('');
  n.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>openModule(b.dataset.module));
}
function openModule(id){
  // Compatibilidad con enlaces antiguos: Producción ahora vive dentro de Clientes.
  if(id==='produccion') id='clientes';
  if(window.CVStudioAccess?.ready&&!window.CVStudioAccess.canModule(id)){const fallback='inicio';currentModule=fallback;nav();document.getElementById('pageTitle').textContent='Acceso restringido';document.getElementById('pageSubtitle').textContent='Tu nivel no permite acceder a este módulo.';document.getElementById('appMain').innerHTML='<section class="panel access-denied"><h2>Acceso denegado</h2><p>No tenés permisos para acceder a este módulo.</p><button class="button primary" data-module="inicio">Volver al Inicio</button></section>';document.querySelector('[data-module="inicio"]')?.addEventListener('click',()=>openModule('inicio'));history.replaceState(null,'','#inicio');return;}
  currentModule=id;nav();
  const meta=modules.find(x=>x[0]===id);
  document.getElementById('pageTitle').textContent=meta[2];
  document.getElementById('pageSubtitle').textContent=meta[3];
  const main=document.getElementById('appMain');
  main.dataset.module=id;
  main.innerHTML=replaceIconTokens(renderers[id]());main.focus();bindModuleActions(id);
  document.getElementById('sidebar').classList.remove('is-open');
  history.replaceState(null,'',`#${id}`);
}
let chartUid=0;
function lineSvg(colors=['#9b5de5','#35d07f','#3b82f6']){
  const uid=`chart-${++chartUid}`;
  const labels=['28 Jul','29 Jul','30 Jul','31 Jul','1 Ago','2 Ago','3 Ago'];
  const series=[[22,38,50,61,57,52,91],[11,24,33,43,39,42,55],[4,9,15,25,20,27,37]];
  const width=1000,height=220,padX=18,padY=12;
  const x=i=>padX+((width-padX*2)/(labels.length-1))*i;
  const y=v=>padY+(height-padY*2)-((v/100)*(height-padY*2));
  const path=values=>values.map((v,i)=>`${i?'L':'M'} ${x(i).toFixed(2)} ${y(v).toFixed(2)}`).join(' ');
  return `<div class="chart-premium" aria-label="Gráfico de inversión y resultados">
    <div class="chart-premium-legend">
      <span style="--c:${colors[0]}"><i></i>Principal</span>
      <span style="--c:${colors[1]}"><i></i>Secundario</span>
      <span style="--c:${colors[2]}"><i></i>Comparativo</span>
    </div>
    <div class="chart-premium-body">
      <div class="chart-y-axis"><b>100%</b><b>75%</b><b>50%</b><b>25%</b><b>0%</b></div>
      <div class="chart-premium-plot">
        <svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img">
          <defs>
            <linearGradient id="${uid}-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${colors[0]}" stop-opacity=".22"/><stop offset="1" stop-color="${colors[0]}" stop-opacity="0"/></linearGradient>
          </defs>
          <g class="chart-premium-grid">${[0,25,50,75,100].map(v=>`<line x1="0" x2="${width}" y1="${y(v)}" y2="${y(v)}"/>`).join('')}</g>
          <path class="chart-premium-area" d="${path(series[0])} L ${x(6)} ${y(0)} L ${x(0)} ${y(0)} Z" fill="url(#${uid}-fill)"/>
          <path class="chart-premium-line main" d="${path(series[0])}" stroke="${colors[0]}"/>
          <path class="chart-premium-line" d="${path(series[1])}" stroke="${colors[1]}"/>
          <path class="chart-premium-line" d="${path(series[2])}" stroke="${colors[2]}"/>
          ${series.map((arr,si)=>arr.map((v,i)=>`<circle class="chart-premium-point" cx="${x(i)}" cy="${y(v)}" r="${si===0?5:4}" fill="${colors[si]}"><title>${labels[i]}: ${v}%</title></circle>`).join('')).join('')}
        </svg>
        <div class="chart-x-axis">${labels.map(l=>`<b>${l}</b>`).join('')}</div>
      </div>
    </div>
  </div>`;
}
function donutChart(value,label,style=''){
  return `<div class="donut donut-hd" style="${style}"><div class="donut-center"><strong>${value}</strong><span>${label}</span></div></div>`;
}

